from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Field names expected on every observation.
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    """Fold raw point observations into an aggregated cell grid.

    Public API (signature and returned shape) is intentionally stable:
    callers rely on the exact result dict and its statistics.
    """
    width, height, cell_size, fill_value, observations = _parse_input(raw)
    if observations is None:
        return {
            "ok": False,
            "error": raw.get("error", "malformed input")
        } if isinstance(raw, dict) else {"ok": False, "error": "malformed input"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = rejected = saturated = 0

    tolerance = cell_size // 2
    for obs in observations:
        x, y, value, quality = _parse_observation(obs)
        if quality is None or quality < MIN_QUALITY:
            # Rejected either because the record is malformed (each malformed
            # observation aborts the whole run) or below the quality bar.
            rejected += 1
            continue

        col = _bin_coord(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _bin_coord(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _parse_input(raw: object) -> tuple[Any, ...]:
    """Validate the top-level payload and return grid geometry + observations.

    Returns ``(width, height, cell_size, fill_value, observations)`` on success
    or ``(None, None, None, None, None)`` when ``raw`` is not a dict (the only
    case that cannot carry a specific error message).
    """
    if not isinstance(raw, dict):
        return (None, None, None, None, None)
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        raise ValueError("missing field")
    grid = raw["grid"]
    if not isinstance(grid, dict):
        raise ValueError("bad grid")
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        raise ValueError("bad grid")

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        raise ValueError("bad width")
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        raise ValueError("bad height")
    if not isinstance(cell_size, int) or cell_size < 1:
        raise ValueError("bad cell size")
    if not isinstance(raw["fill_value"], int):
        raise ValueError("bad fill value")
    observations = raw["observations"]
    if not isinstance(observations, list):
        raise ValueError("bad observations")

    return (
        width,
        height,
        cell_size,
        raw["fill_value"],
        observations,
    )


def _parse_observation(obs: object) -> tuple[Any, ...]:
    """Validate one observation, returning its fields or a failed tuple.

    Returns ``(x, y, value, quality)`` on success, or ``(None, None, None, None)``
    when the record is malformed.
    """
    if not isinstance(obs, dict):
        return (None, None, None, None)
    if any(field not in obs for field in _OBS_FIELDS):
        return (None, None, None, None)
    x, y, value, quality = obs["x"], obs["y"], obs["value"], obs["quality"]
    if not (
        isinstance(x, int)
        and isinstance(y, int)
        and isinstance(value, int)
        and isinstance(quality, int)
        and 0 <= quality <= 100
    ):
        return (None, None, None, None)
    return (x, y, value, quality)


def _bin_coord(coord: int, cell_size: int, dim: int, tolerance: int) -> int | None:
    """Map a raw coordinate to a cell index, applying the edge clamp.

    Returns the cell index, or ``None`` when the coordinate falls outside the
    grid (and cannot be clamped within tolerance).
    """
    if coord < 0:
        return None
    cell = coord // cell_size
    if cell < dim:
        return cell
    # Coordinate lands in the slack between the last cell's nominal edge and
    # the hard boundary; clamp it into the final cell if it is close enough.
