from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Field names expected on every observation.
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    """Fold raw point observations into an aggregated cell grid.

    Public API (signature and returned shape) is intentionally stable:
    callers rely on the exact result dict and its reported statistics.
    """
    parsed = _parse_input(raw)
    if parsed is None:
        return {"ok": False, "error": "malformed input"}
    if isinstance(parsed, str):
        return {"ok": False, "error": parsed}
    width, height, cell_size, fill_value, observations = parsed

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = rejected = saturated = 0

    tolerance = cell_size // 2
    for obs in observations:
        parsed_obs = _parse_observation(obs)
        if isinstance(parsed_obs, str):
            return {"ok": False, "error": parsed_obs}
        x, y, value, quality = parsed_obs

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col = _bin_coord(x, cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue
        row = _bin_coord(y, cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _parse_input(raw: object) -> tuple[Any, ...] | str | None:
    """Validate the top-level payload.

    Returns a ``(width, height, cell_size, fill_value, observations)`` tuple on
    success, an error-message string for a specific validation failure, or
    ``None`` when ``raw`` is not a dict (no specific message applies).
    """
    if not isinstance(raw, dict):
        return None
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid"
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"

    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    if not isinstance(raw["fill_value"], int):
        return "bad fill value"
    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations"

    return width, height, cell_size, raw["fill_value"], observations


def _parse_observation(obs: object) -> tuple[int, int, int, int] | str:
    """Validate one observation.

    Returns its ``(x, y, value, quality)`` fields on success, or an error
    string when the record is malformed.
    """
    if not isinstance(obs, dict):
        return "bad observation"
    if any(field not in obs for field in _OBS_FIELDS):
        return "bad observation"
    x, y, value, quality = obs["x"], obs["y"], obs["value"], obs["quality"]
    if not (
        isinstance(x, int)
        and isinstance(y, int)
        and isinstance(value, int)
        and isinstance(quality, int)
        and 0 <= quality <= 100
    ):
        return "bad observation"
    return x, y, value, quality


def _bin_coord(coord: int, cell_size: int, dim: int, tolerance: int) -> int | None:
    """Map a raw coordinate to a cell index, applying the edge clamp.

    Returns the cell index, or ``None`` when the coordinate falls outside the
    grid and cannot be clamped within tolerance.
    """
    if coord < 0:
        return None
    cell = coord // cell_size
    if cell < dim:
        return cell
    # The coordinate lands in the slack between the last cell's nominal edge
    # and the hard boundary; clamp it into the final cell when close enough.
    if coord - dim * cell_size < tolerance:
        return dim - 1
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
